import json
import time
from datetime import datetime

# 模擬資料庫，儲存步數記錄
steps_data = []

# 紀錄的ID計數器
next_id = 1

def handle(method, path, body):
    global steps_data, next_id

    if method == "GET" and path == "/steps":
        return (200, {"steps": steps_data})

    elif method == "POST" and path == "/steps":
        try:
            data = json.loads(body.decode())
            steps = data.get("steps")

            if steps is None or not isinstance(steps, int) or steps < 0:
                return (400, {"error": "步數必須是大於等於0的整數"})

            # 建立新的記錄
            new_step = {
                "id": next_id,
                "steps": steps,
                "timestamp": datetime.now().isoformat()
            }

            steps_data.append(new_step)
            next_id += 1

            return (201, {"message": "步數記錄新增成功", "step": new_step})
        except json.JSONDecodeError:
            return (400, {"error": "無效的JSON格式"})

    elif method == "GET" and path == "/steps/today":
        # 獲取今天的步數總和
        today = datetime.now().strftime('%Y-%m-%d')
        today_steps = [s for s in steps_data if s["timestamp"].startswith(today)]
        total_steps = sum(s["steps"] for s in today_steps)

        return (200, {"steps": total_steps})

    elif method == "DELETE" and path.startswith("/steps/"):
        # 提取步數記錄的ID
        try:
            step_id = int(path.split("/")[3])
        except (ValueError, IndexError):
            return (400, {"error": "無效的步數記錄ID"})

        # 找到並刪除對應的記錄
        for i, step in enumerate(steps_data):
            if step["id"] == step_id:
                steps_data.pop(i)
                return (200, {"message": "步數記錄已刪除"})

        # 如果沒有找到指定ID的記錄
        return (404, {"error": "找不到指定的步數記錄"})

    else:
        return (404, {"error": "路徑未找到"})

