document.addEventListener('DOMContentLoaded', function() {
    const stepForm = document.getElementById('stepForm');
    const stepsHistory = document.getElementById('stepsHistory');
    const todayValue = document.getElementById('todayValue');

    // 獲取今天的步數
    fetch('api/steps/today')
        .then(response => response.json())
        .then(data => {
            if (data.steps !== undefined) {
                todayValue.textContent = data.steps + ' 步';
            } else {
                todayValue.textContent = '無記錄';
            }
        })
        .catch(error => {
            console.error('獲取今天步數時出錯:', error);
            todayValue.textContent = '錯誤';
        });

    // 獲取歷史步數記錄
    fetch('api/steps')
        .then(response => response.json())
        .then(data => {
            displaySteps(data.steps || []);
        })
        .catch(error => {
            console.error('獲取步數記錄時出錯:', error);
        });

    // 提交新步數
    stepForm.addEventListener('submit', function(e) {
        e.preventDefault();
        const stepsInput = document.getElementById('steps');
        const steps = parseInt(stepsInput.value);

        if (isNaN(steps) || steps < 0) {
            alert('請輸入有效的步數');
            return;
        }

        fetch('api/steps', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ steps: steps })
        })
        .then(response => response.json())
        .then(data => {
            stepsInput.value = '';
            // 重新獲取並顯示所有記錄
            fetch('api/steps')
                .then(response => response.json())
                .then(data => {
                    displaySteps(data.steps || []);
                    // 更新今天步數
                    fetch('api/steps/today')
                        .then(response => response.json())
                        .then(todayData => {
                            if (todayData.steps !== undefined) {
                                todayValue.textContent = todayData.steps + ' 步';
                            } else {
                                todayValue.textContent = '無記錄';
                            }
                        });
                });
        })
        .catch(error => {
            console.error('新增步數時出錯:', error);
            alert('新增步數失敗');
        });
    });

    // 顯示步數記錄
    function displaySteps(steps) {
        stepsHistory.innerHTML = '';
        if (steps.length === 0) {
            stepsHistory.innerHTML = '<li>無記錄</li>';
            return;
        }

        // 按時間倒序排列
        steps.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

        steps.forEach(step => {
            const li = document.createElement('li');
            const date = new Date(step.timestamp);
            li.textContent = `${step.steps} 步 - ${date.toLocaleString('zh-Hant')}`;

            // 添加刪除按鈕
            const deleteBtn = document.createElement('button');
            deleteBtn.textContent = '刪除';
            deleteBtn.onclick = function() {
                fetch(`api/steps/${step.id}`, {
                    method: 'DELETE'
                })
                .then(response => {
                    if (response.ok) {
                        // 重新獲取並顯示所有記錄
                        fetch('api/steps')
                            .then(response => response.json())
                            .then(data => {
                                displaySteps(data.steps || []);
                                // 更新今天步數
                                fetch('api/steps/today')
                                    .then(response => response.json())
                                    .then(todayData => {
                                        if (todayData.steps !== undefined) {
                                            todayValue.textContent = todayData.steps + ' 步';
                                        } else {
                                            todayValue.textContent = '無記錄';
                                        }
                                    });
                            });
                    } else {
                        console.error('刪除步數記錄失敗');
                        alert('刪除失敗');
                    }
                })
                .catch(error => {
                    console.error('刪除步數記錄時出錯:', error);
                    alert('刪除失敗');
                });
            };

            li.appendChild(deleteBtn);
            stepsHistory.appendChild(li);
        });
    }
});

